#!/usr/bin/env bash
# Create the databases (`hosted-postgres`, environment `hybrid`). Generated by trestle; re-render to update.
set -euo pipefail
cd "$(dirname "$0")/.."

# Secrets kept in secrets.env (git-ignored) are read like exported ones.
if [ -f secrets.env ]; then
  set -a
  # shellcheck source=/dev/null
  . ./secrets.env
  set +a
fi

# save_secret NAME VALUE: record NAME in secrets.env (and this shell), unless secrets.env
# already sets it.
save_secret() {
  if [ -f secrets.env ] && grep -q "^$1=" secrets.env; then
    echo "secrets.env already sets $1; leaving it as is"
  else
    (umask 077 && printf '%s=%s\n' "$1" "$2" >> secrets.env)
    echo "saved $1 to secrets.env"
  fi
  export "$1=$2"
}

password_var='PG_PASSWORD'
export PGHOST='lakehouse.abc123example.us-east-1.rds.amazonaws.com'
export PGPORT='5432'
export PGUSER='lakehouse'
export PGPASSWORD="${!password_var:?set $password_var (see README.md)}"
export PGSSLMODE='require'
for db in 'unitycatalog' 'mlflow' ; do
  if [ "$(psql -d postgres -tAc "SELECT 1 FROM pg_database WHERE datname = '$db'")" = 1 ]; then
    echo "database $db exists"
  else
    psql -d postgres -qc "CREATE DATABASE \"$db\""
    echo "created database $db"
  fi
done
